SELECT t.title_id, t.title
FROM titles t
WHERE NOT EXISTS (
  SELECT 1 FROM watch_history w WHERE w.title_id = t.title_id
)
ORDER BY t.title_id;

SELECT t.tweet_id, t.author_handle, t.body
FROM tweets t
WHERE NOT EXISTS (
  SELECT 1 FROM mute_list m WHERE m.muted_handle = t.author_handle
)
ORDER BY t.tweet_id;
